#include <algorithm>
#include <array>
#include <bit>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <numeric>
#include <random>
#include <vector>
using U=uint64_t;
constexpr int INPUTS=26,GATES=70,WIRES=96;
struct Gate{int op,a,b;bool operator==(const Gate&)const=default;};
using Net=std::array<Gate,GATES>;
#include "full_variable_stratum_seeds.hpp"
std::vector<U>val,target,negative,masks;
int words=0,lastRaw=0,lastLive=0;
std::array<bool,GATES>activeMask(const Net&c){std::array<bool,WIRES>live{};live[WIRES-1]=true;std::array<bool,GATES>out{};for(int j=GATES-1;j>=0;j--)if(live[INPUTS+j]){out[j]=true;live[c[j].a]=live[c[j].b]=true;}return out;}
int activeCount(const Net&c){auto a=activeMask(c);return std::count(a.begin(),a.end(),true);}
#include "stratum_undominated_full.hpp"
int eval(const Net&c){for(int j=0;j<GATES;j++){auto g=c[j];for(int k=0;k<words;k++)val[(INPUTS+j)*words+k]=g.op?(val[g.a*words+k]|val[g.b*words+k]):(val[g.a*words+k]&val[g.b*words+k]);}lastRaw=0;for(int k=0;k<words;k++)lastRaw+=std::popcount((val[(WIRES-1)*words+k]^target[k])&masks[k]);lastLive=activeCount(c);if(!lastRaw)classifyStratum(c);else lastViolations=lastNonread=lastShared=lastNested=lastDominated=0;return 1000*lastRaw+lastLive;}
bool valid(const Net&c){for(int j=0;j<GATES;j++)if(c[j].op<0||c[j].op>1||c[j].a<0||c[j].b<0||c[j].a>=INPUTS+j||c[j].b>=INPUTS+j)return false;return true;}
std::vector<Gate> compact(const Net&c){auto live=activeMask(c);std::array<int,WIRES>mp{};std::iota(mp.begin(),mp.begin()+INPUTS,0);std::vector<Gate>out;for(int j=0;j<GATES;j++)if(live[j]){auto g=c[j];mp[INPUTS+j]=INPUTS+out.size();out.push_back({g.op,mp[g.a],mp[g.b]});}return out;}
Net pad(std::vector<Gate>gs){if(gs.empty()||gs.size()>GATES)std::abort();auto out=gs.back();gs.pop_back();while(gs.size()<GATES-1)gs.push_back({1,0,0});gs.push_back(out);Net c;std::copy(gs.begin(),gs.end(),c.begin());if(!valid(c))std::abort();return c;}
#include "repair_shrink_full.hpp"
#include "neutral_pair_care_full.hpp"
#include "scatter_spares_full.hpp"
void show(const Net&c,const char*kind,long long it,double seconds){eval(c);auto gs=compact(c);std::cout<<"{\"kind\":\""<<kind<<"\",\"seconds\":"<<seconds<<",\"iterations\":"<<it<<",\"raw\":"<<lastRaw<<",\"live\":"<<gs.size()<<",\"violations\":"<<lastViolations<<",\"nonread\":"<<lastNonread<<",\"shared\":"<<lastShared<<",\"nested\":"<<lastNested<<",\"dominated\":"<<lastDominated<<",\"output\":"<<INPUTS+gs.size()-1<<",\"gates\":[";for(int j=0;j<(int)gs.size();j++){if(j)std::cout<<',';auto g=gs[j];std::cout<<'['<<g.op<<','<<g.a<<','<<g.b<<']';}std::cout<<"]}"<<std::endl;}
bool expandBig(Net&c,std::mt19937&rng){auto gs=compact(c);if(gs.size()+4>GATES)return false;std::vector<int>uses(INPUTS+gs.size());for(auto g:gs){uses[g.a]++;uses[g.b]++;}std::vector<int>choices;for(int j=0;j<(int)gs.size();j++){auto g=gs[j];if(g.a<INPUTS||g.b<INPUTS||g.a==g.b)continue;auto a=gs[g.a-INPUTS],b=gs[g.b-INPUTS];if(a.op==1-g.op&&b.op==1-g.op&&uses[g.a]==1&&uses[g.b]==1)choices.push_back(j);}if(choices.empty())return false;int j=choices[rng()%choices.size()],h=gs[j].a-INPUTS,k=gs[j].b-INPUTS;auto oldh=gs[h],oldk=gs[k];std::vector<int>mp(INPUTS+gs.size());std::iota(mp.begin(),mp.begin()+INPUTS,0);std::vector<Gate>out;auto add=[&](int op,int a,int b){int w=INPUTS+out.size();out.push_back({op,a,b});return w;};for(int z=0;z<(int)gs.size();z++){if(z==h||z==k)continue;if(z==j){int a=mp[oldh.a],b=mp[oldh.b],cc=mp[oldk.a],d=mp[oldk.b],op=gs[j].op,mid=1-op;int u=add(op,a,cc),v=add(op,b,d),w=add(op,a,d),x=add(op,b,cc),y=add(mid,u,v),zz=add(mid,w,x);mp[INPUTS+z]=add(mid,y,zz);}else{auto g=gs[z];mp[INPUTS+z]=add(g.op,mp[g.a],mp[g.b]);}}auto nc=pad(out);eval(c);std::vector<U>before(words);for(int z=0;z<words;z++)before[z]=val[(WIRES-1)*words+z];eval(nc);for(int z=0;z<words;z++)if(before[z]!=val[(WIRES-1)*words+z])std::abort();c=nc;return true;}
bool expandSmall(Net&c,std::mt19937&rng){auto gs=compact(c);std::vector<int>uses(INPUTS+gs.size());for(auto g:gs){uses[g.a]++;uses[g.b]++;}std::vector<std::pair<int,int>>choices;for(int j=0;j<(int)gs.size();j++)for(int h:{gs[j].a,gs[j].b})if(h>=INPUTS&&gs[h-INPUTS].op!=gs[j].op){int cost=uses[h]==1?1:2;if(gs.size()+cost<=GATES)choices.push_back({j,h-INPUTS});}if(choices.empty())return false;auto [j,h]=choices[rng()%choices.size()];bool remove=uses[INPUTS+h]==1;int other=gs[j].a==INPUTS+h?gs[j].b:gs[j].a;auto ih=gs[h];std::vector<int>mp(INPUTS+gs.size());std::iota(mp.begin(),mp.begin()+INPUTS,0);std::vector<Gate>out;auto add=[&](int op,int a,int b){int w=INPUTS+out.size();out.push_back({op,a,b});return w;};for(int z=0;z<(int)gs.size();z++){if(z==h&&remove)continue;if(z==j){int op=gs[j].op,x=mp[other],a=mp[ih.a],b=mp[ih.b],u=add(op,x,a),v=add(op,x,b);mp[INPUTS+z]=add(1-op,u,v);}else{auto g=gs[z];mp[INPUTS+z]=add(g.op,mp[g.a],mp[g.b]);}}auto nc=pad(out);eval(c);std::vector<U>before(words);for(int k=0;k<words;k++)before[k]=val[(WIRES-1)*words+k];eval(nc);for(int k=0;k<words;k++)if(before[k]!=val[(WIRES-1)*words+k])std::abort();c=nc;return true;}
bool expand(Net&c,std::mt19937&rng){return rng()%5==0?expandBig(c,rng):expandSmall(c,rng);}
void mutate(Net&c,std::mt19937&rng){int strength=1+(rng()%100<15);for(int t=0;t<strength;t++){int j=rng()%GATES,kind=rng()%9;auto&g=c[j];if(kind==0)g.op=1-g.op;else if(kind<4)g.a=rng()%(INPUTS+j);else if(kind<7)g.b=rng()%(INPUTS+j);else if(kind==7){int a=g.a,b=g.b;if(a<INPUTS)std::swap(a,b);if(a>=INPUTS){int h=a-INPUTS;int uses=0;for(int k=h+1;k<GATES;k++)uses+=(c[k].a==a)+(c[k].b==a);if(uses==1&&c[h].op==g.op&&b<INPUTS+h){int displaced=c[h].b;c[h].b=b;g.a=a;g.b=displaced;}}}else{int h=rng()%GATES;if(h<j)std::swap(h,j);if(h!=j&&c[h].a<INPUTS+j&&c[h].b<INPUTS+j){std::swap(c[h],c[j]);for(int k=j+1;k<GATES;k++){if(c[k].a==INPUTS+j)c[k].a=INPUTS+h;else if(c[k].a==INPUTS+h)c[k].a=INPUTS+j;if(c[k].b==INPUTS+j)c[k].b=INPUTS+h;else if(c[k].b==INPUTS+h)c[k].b=INPUTS+j;}}}}}
int scalarErrors(const Net&c,const std::vector<int>&rows){int errors=0;for(int k=0;k<(int)rows.size();k++){std::array<bool,WIRES>w{};for(int i=0;i<INPUTS;i++)w[i]=(rows[k]>>i)&1;for(int j=0;j<GATES;j++){auto g=c[j];w[INPUTS+j]=g.op?(w[g.a]||w[g.b]):(w[g.a]&&w[g.b]);}errors+=w.back()!=(k<52);}return errors;}
int main(int argc,char**argv){if(argc!=4)return 2;std::ifstream f(argv[1]);std::vector<int>rows;int r;while(f>>r)rows.push_back(r);if(rows.size()!=756)return 3;words=(rows.size()+63)/64;val.resize(WIRES*words);target.resize(words);negative.resize(words);masks.resize(words);for(int k=0;k<(int)rows.size();k++){U bit=U(1)<<(k%64);for(int i=0;i<INPUTS;i++)if(rows[k]>>i&1)val[i*words+k/64]|=bit;if(k<52)target[k/64]|=bit;else negative[k/64]|=bit;masks[k/64]|=bit;}std::mt19937 rng(std::stoul(argv[3]));int seconds=std::stoi(argv[2]);for(auto gs:nonlinearSeeds){auto c=pad(gs);eval(c);if(lastRaw||lastLive!=(int)gs.size())return 4;}std::cerr<<"PASS755 exact nonlinear seed controls"<<std::endl;Net probe=pad(nonlinearSeeds[0]);for(int z=0;z<1000;z++){Net next=probe;mutate(next,rng);if(valid(next))probe=next;eval(probe);if(lastRaw!=scalarErrors(probe,rows))return 9;auto packed=pad(compact(probe));eval(packed);if(lastRaw!=scalarErrors(probe,rows))return 10;}std::cerr<<"PASS1000 scalar/bitset and compaction differential controls"<<std::endl;if(seconds<0)return 0;Net control=pad(nonlinearSeeds[0]);int rounds=0;while(shrinkExact(control)){rounds++;control=pad(compact(control));if(rounds>GATES)return 5;}eval(control);if(lastRaw||lastLive>65)return 6;std::cerr<<"PASS66-to-"<<lastLive<<" exact shrink control; rounds="<<rounds<<std::endl;if(lastLive<=63){show(control,"HIT",0,0);return 0;}for(int k=0;k<100;k++){auto c=control;expand(c,rng);eval(c);if(lastRaw)return 7;}std::cerr<<"PASS100 exact CNF/DNF expansion controls"<<std::endl;if(seconds==0)return 0;auto start=std::chrono::steady_clock::now();auto elapsed=[&]{return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();};std::vector<int>eligible,nestedEligible;for(int z=0;z<(int)nonlinearSeeds.size();z++){auto seedNet=pad(nonlinearSeeds[z]);eval(seedNet);if(inStratum()){eligible.push_back(z);if(lastNested)nestedEligible.push_back(z);}}if(eligible.empty()||nestedEligible.empty())return 11;std::cerr<<"STRATUM eligible="<<eligible.size()<<" nested="<<nestedEligible.size()<<std::endl;auto chooseSeed=[&](){const auto&ids=rng()%2?nestedEligible:eligible;return pad(nonlinearSeeds[ids[rng()%ids.size()]]);};Net c=chooseSeed(),best=c;int bs=activeCount(best),sc=eval(c);if(!inStratum())return 12;std::vector<Net>pool{c};long long it=0,accepted=0;double nextReport=60;show(best,"best",it,elapsed());while(elapsed()<seconds){if(elapsed()>=nextReport){show(c,"progress",it,elapsed());nextReport+=60;}if(it&&it%500000==0){c=rng()%2?pool[rng()%pool.size()]:chooseSeed();c=pad(compact(c));if(rng()%2)while(true){auto trial=c;if(!shrinkExact(trial))break;trial=pad(compact(trial));eval(trial);if(lastRaw)return 13;if(lastLive<=63){show(trial,"HIT",it,elapsed());return 0;}if(!inStratum())break;c=trial;if(lastLive<bs){bs=lastLive;best=c;show(best,"best",it,elapsed());}}if(rng()%2)c=scatterSpareSlots(c,rng);sc=eval(c);if(!inStratum())return 8;}Net nc=c;if(it%16384==0)neutralPairCare(nc,rng);else if(rng()%100<3)expand(nc,rng);else mutate(nc,rng);it++;if(!valid(nc))continue;int ns=eval(nc);if(lastRaw)continue;if(lastLive<=63){show(nc,"HIT",it,elapsed());return 0;}if(!inStratum())continue;if(lastLive<bs){bs=lastLive;best=nc;show(best,"best",it,elapsed());}double temp=0.25+1.5*double((it/100000)%7)/6.0;if(ns<=sc||std::generate_canonical<double,32>(rng)<std::exp(double(sc-ns)/temp)){c=nc;sc=ns;accepted++;if(accepted%10000==0){if(pool.size()<64)pool.push_back(c);else pool[rng()%pool.size()]=c;}}}for(auto nc:pool)show(nc,"pool",it,elapsed());show(best,"final",it,elapsed());std::cerr<<"accepted="<<accepted<<" repair_calls="<<repairCalls<<" repair_expressions="<<repairExpressions<<" pair_calls="<<pairCalls<<" pair_options="<<pairOptions<<" pair_moves="<<pairMoves<<" pair_opchanging_options="<<pairOpChangingOptions<<std::endl;return 0;}
